//Данный драйвер выполняется на уровне IRQL - PASSIVE_LEVL.#include <ntddk.h> //Стандартная библиотека для всех драйверов. #include <ntstrsafe.h> // Библиотека сравнения строк ( strstr ).PVOID IsRegCollback = NULL; NTKERNELAPI PCHAR PsGetProcessImageFileName(PEPROCESS Process); // Объявление функции тк ее нет ни в оодной библиотеке, но она есть в самом ядре.OB_PREOP_CALLBACK_STATUS AntiKill ( //Объявление функции. (Имя исправлено для соответствия DriverEntry)    PVOID RegistrationContext, //Заполнение необходимой информацией. (Указатель на то, что тут нету настройки для временного отключения функции).    POB_PRE_OPERATION_INFORMATION OperationInformation //Говорим получать информацию из внешнего мира до выполнения действий (PRE - Перед).){ // И тут начинается функция.    UNREFERENCED_PARAMETER(RegistrationContext); // Сообщение компилятору дабы он не выдавал ошибку о том что была передача "RegistrationContext", но она пуста и не было синего экрана смерти.	    if(OperationInformation->ObjectType == *PsProcessType){ //Если операция происходит именно над процессом то...        PEPROCESS ProcessNadKotoromChtoToDelaut = (PEPROCESS)OperationInformation->Object; // Получение структуры процесса над которым что то происходит.		        if(ProcessNadKotoromChtoToDelaut == PsGetCurrentProcess()){            return OB_PREOP_SUCCESS;        } //Эти строки написаны чтобы само приложение могло само с собой что то делать. Так как далее будет проверка на         // обычное имя процесса, то поэтому любой процесс который назовет себя "hello.exe" сможет взаимодействовать        // и с другими процессами такого же имени. В более профессиональных драйверах делается проверка по пути или вообще по         // криптографическому алгоритму.	        PCHAR ProcessName = PsGetProcessImageFileName(ProcessNadKotoromChtoToDelaut); // Получаем нормальное имя процесса над которым что то делают, а не огромную структуру.	        if (ProcessName != NULL && (strstr(ProcessName, "hello.exe") != NULL || strstr(ProcessName, "Hello.exe") != NULL)){            // Это сравнение имен процесса над которым что то делают и имени приложения. на разных версиях            // Виндовс имя может отличаться.		            if(OperationInformation->Operation == OB_OPERATION_HANDLE_CREATE){ //Если что то пытается получить опасные права доступа то...	                        OperationInformation->Parameters->CreateHandleInformation.DesiredAccess &= ~PROCESS_TERMINATE; //Срез прав на закрытие.                OperationInformation->Parameters->CreateHandleInformation.DesiredAccess &= ~PROCESS_VM_WRITE;  //Срез прав на внедрение в память к процессу.                OperationInformation->Parameters->CreateHandleInformation.DesiredAccess &= ~PROCESS_SUSPEND_RESUME; //Срез прав на остановление процесса.                // Любому процессу разрешено читать и тд, но "&= ~" это побитовое "И не".                // То есть даем разрешение на все что хотят, но не на опасные права.            }		            //Тут если право хотят "отсудить", продублировать, то снова все опасное отбираем.             else if (OperationInformation->Operation == OB_OPERATION_HANDLE_DUPLICATE){                OperationInformation->Parameters->DuplicateHandleInformation.DesiredAccess &= ~PROCESS_TERMINATE;                OperationInformation->Parameters->DuplicateHandleInformation.DesiredAccess &= ~PROCESS_VM_WRITE;                OperationInformation->Parameters->DuplicateHandleInformation.DesiredAccess &= ~PROCESS_SUSPEND_RESUME;            }        }    }    return OB_PREOP_SUCCESS; //Завершение перехватчика.}VOID Unload(PDRIVER_OBJECT DriverObject) { //Функция выгрузки, если бы ее не было, то драйвер был бы не выгружаемым. Передаем указатель на объект этого драйвера.    UNREFERENCED_PARAMETER(DriverObject);     if (IsRegCollback != NULL) { //Если была регистрация перехватчика,        ObUnregisterCallbacks(IsRegCollback); //то мы ее снимаем.    }}NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath){ // А это главная функция, с которой начинается запуск перехватчика и запуск всего драйвера. Аналог int main у обысных программ.    UNREFERENCED_PARAMETER(RegistryPath); // Сообщение о том, что мы не использем этот указатель (Указатель на строку в реестре для драйвера). Тут уже не будет записки о том, что объект не используется,                                          //так как он использоваться уже будет в качестве указателя на функцию выгрузки.	    NTSTATUS status; //Будет использоваться при поиске ошибок в регистрации.	    DriverObject->DriverUnload = Unload; // Это указатель где лежит функция для выгрузки. Интересный факт, если бы этой строки не было, то драйвер бы никогда не выгрузился из системы,                                        // только после полной перезагрузки.	    //Следующие строк 20 были скопированы из документации и представляют из себя функцию регистрации перехватчика, тут особо ничего интересного,    // и никто их вручную не пишет. Самые интересные буду комментировать.	    // Настройка структуры для перехвата событий процесса.    OB_OPERATION_REGISTRATION opRegistration;    RtlZeroMemory(&opRegistration, sizeof(opRegistration));    opRegistration.ObjectType = PsProcessType;    opRegistration.Operations = OB_OPERATION_HANDLE_CREATE | OB_OPERATION_HANDLE_DUPLICATE;    opRegistration.PreOperation = AntiKill; //Функция-перехватчик.    opRegistration.PostOperation = NULL;    // Настройка общей регистрации колбека перехватчика.    OB_CALLBACK_REGISTRATION cbRegistration;    RtlZeroMemory(&cbRegistration, sizeof(cbRegistration));    cbRegistration.Version = OB_FLT_REGISTRATION_VERSION;    cbRegistration.OperationRegistrationCount = 1;    cbRegistration.RegistrationContext = NULL;    // Высота (Altitude) — должна быть уникальной текстовой строкой. Чем она больше, тем первей драйвер получит сообщение.    RtlInitUnicodeString(&cbRegistration.Altitude, L"388888");     cbRegistration.OperationRegistration = &opRegistration;    // Регистрация перехватчика в системе.    status = ObRegisterCallbacks(&cbRegistration, &IsRegCollback);    if (!NT_SUCCESS(status)) { // Это проверка на то, что прехватчик успешно зарегистрировался в системе.        return status; //Возврат ошибки системе.    }	    return STATUS_SUCCESS; // Если все хорошо, возвращаем системе статус успеха.  }